CREATE TABLE public.devices (
    id uuid NOT NULL,
    "createdAt" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "userId" uuid NOT NULL,
    name text,
    "pushPlatform" text,
    "pushSubscription" jsonb,
    "hasPushSubscription" boolean
);


--
-- Name: diary_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.diary_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    date date NOT NULL,
    meal_type text NOT NULL,
    food_id uuid,
    food_name text NOT NULL,
    servings numeric(10,2) DEFAULT 1 NOT NULL,
    serving_unit text DEFAULT 'serving'::text NOT NULL,
    calories numeric(10,2) DEFAULT 0 NOT NULL,
    protein numeric(10,2) DEFAULT 0 NOT NULL,
    carbs numeric(10,2) DEFAULT 0 NOT NULL,
    fat numeric(10,2) DEFAULT 0 NOT NULL,
    fiber numeric(10,2) DEFAULT 0 NOT NULL,
    sodium numeric(10,2) DEFAULT 0 NOT NULL,
    sugar numeric(10,2) DEFAULT 0 NOT NULL,
    is_quick_add boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


